const wikiTitles={1:"Lake Coatepeque",2:"Santa Ana Volcano",3:"El Tunco",4:"San Salvador (volcano)",5:"San Salvador",6:"Suchitoto",7:"Conchagua (volcano)",8:"Río Sapo",9:"El Mozote",10:"Lake Alegría",11:"El Cuco",12:"Nahuizalco",13:"Joya de Cerén",14:"Los Cóbanos",15:"Pupusa",16:"Concepción de Ataco",17:"Montecristo Trifinio",18:"Gulf of Fonseca",19:"El Salvador International Airport",20:"Tazumal",21:"San Andrés, El Salvador",22:"Cihuatán",41:"Casa Blanca, El Salvador"};
async function loadImages(){
 const titleToPlace=new Map(places.map(p=>[wikiTitles[p.id],p]));
 try{
  const titles=[...titleToPlace.keys()].join("|");
  const url="https://en.wikipedia.org/w/api.php?action=query&origin=*&format=json&redirects=1&prop=pageimages|info&inprop=url&pithumbsize=900&titles="+encodeURIComponent(titles);
  const response=await fetch(url);
  const payload=await response.json();
  Object.values(payload.query?.pages||{}).forEach(page=>{
   const place=titleToPlace.get(page.title)||places.find(p=>wikiTitles[p.id]===page.title);
   if(place&&!place.image&&page.thumbnail?.source){place.image=page.thumbnail.source;place.imagePage=page.fullurl}
  });
 }catch(error){console.info("Destination photos unavailable; using category artwork.",error)}
 render();if(selected)openPlace(selected);
}
